<script setup>
import { onMounted, reactive, ref } from 'vue'
import { financeApi } from '../api'
import { useFinanceSession } from '../session'
import { errorMessage } from '../utils'
import FinanceModal from '../components/FinanceModal.vue'
import FieldErrors from '../components/FieldErrors.vue'
const session = useFinanceSession(), rows = ref([]), loading = ref(false), busy = ref(false), modal = ref(false), selected = ref(null), error = ref(''), errors = ref({}), notice = ref(''), form = reactive({})
const roles = { finance_manager: 'مدير مالي', finance_accountant: 'محاسب', finance_entry: 'موظف إدخال' }
const descriptions = { finance_manager: 'جميع صلاحيات المالية، بما فيها الاعتماد والتصحيح وإدارة المستخدمين وجميع الفروع.', finance_accountant: 'الإيرادات والمصروفات والمشتريات والموردون والتقارير والتصدير، ضمن الفروع المحددة.', finance_entry: 'إدخال الإيرادات والمصروفات والمشتريات وعرض الموردين، ضمن الفروع المحددة.' }
async function load() { loading.value = true; error.value = ''; try { rows.value = (await financeApi.users()).users } catch (e) { error.value = errorMessage(e) } finally { loading.value = false } }
function open(row = null) { selected.value = row; error.value = ''; errors.value = {}; Object.assign(form, { name: row?.name || '', email: row?.email || '', password: '', role: row?.role || 'finance_entry', is_active: row?.is_active ?? true, branch_uuids: [...(row?.branch_uuids || [])] }); modal.value = true }
async function save() {
  if (busy.value) return
  busy.value = true; error.value = ''; errors.value = {}
  try { await financeApi.saveUser({ ...form }, selected.value?.uuid); modal.value = false; notice.value = 'تم حفظ المستخدم وصلاحياته المالية.'; await load() }
  catch (e) { error.value = errorMessage(e); errors.value = e.response?.data?.errors || {} }
  finally { busy.value = false; form.password = '' }
}
onMounted(load)
</script>
<template><div class="page-intro"><div><h2>الفريق المالي</h2><p class="muted">أدوار مالية مستقلة، ووصول محدد إلى الفروع.</p></div><button class="primary" @click="open()"><FinanceIcon name="plus" /> إضافة مستخدم مالي</button></div><p class="notice success" v-if="notice" role="status">{{ notice }}</p><p v-if="error && !modal" class="notice danger" role="alert">{{ error }} <button @click="load">إعادة المحاولة</button></p><section class="card"><div v-if="loading" class="loading" role="status">جارٍ تحميل المستخدمين…</div><div v-else class="table-wrap finance-responsive-wrap"><table class="finance-responsive-table" role="table"><thead role="rowgroup"><tr role="row"><th role="columnheader">المستخدم</th><th role="columnheader">الدور المالي</th><th role="columnheader">الفروع</th><th role="columnheader">الحالة</th><th role="columnheader">الإجراء</th></tr></thead><tbody role="rowgroup"><tr v-for="row in rows" :key="row.uuid" role="row"><td role="cell"><span class="finance-cell-label" aria-hidden="true">المستخدم</span><div class="finance-cell-value"><strong>{{ row.name }}</strong><small>{{ row.email }}</small></div></td><td role="cell"><span class="finance-cell-label" aria-hidden="true">الدور المالي</span><div class="finance-cell-value">{{ roles[row.role] }}</div></td><td role="cell"><span class="finance-cell-label" aria-hidden="true">الفروع</span><div class="finance-cell-value">{{ row.role === 'finance_manager' ? 'جميع الفروع' : session.branches.filter(b => row.branch_uuids.includes(b.uuid)).map(b => b.name).join('، ') || 'لا توجد فروع' }}</div></td><td role="cell"><span class="finance-cell-label" aria-hidden="true">الحالة</span><div class="finance-cell-value"><span class="badge" :class="row.is_active ? 'approved' : 'draft'">{{ row.is_active ? 'نشط' : 'معطّل' }}</span></div></td><td class="finance-cell-actions" role="cell"><span class="finance-cell-label" aria-hidden="true">الإجراء</span><div class="finance-cell-value"><button @click="open(row)"><FinanceIcon name="pencil" />تعديل</button></div></td></tr></tbody></table></div></section><FinanceModal v-if="modal" title="حساب مالي" :busy="busy" @close="modal = false"><form @submit.prevent="save"><div class="modal-body"><p class="notice danger" v-if="error" role="alert">{{ error }}</p><FieldErrors :errors="errors"/><div class="form-grid"><label>الاسم<input v-model="form.name" required maxlength="120"></label><label>البريد الإلكتروني<input v-model="form.email" required type="email" maxlength="255" dir="ltr"></label></div><label>{{ selected ? 'كلمة مرور جديدة (اختياري)' : 'كلمة المرور' }}<input v-model="form.password" type="password" :required="!selected" minlength="12" autocomplete="new-password" dir="ltr"><small>12 حرفًا على الأقل، مع أحرف كبيرة وصغيرة وأرقام.</small></label><label>الدور<select v-model="form.role"><option v-for="(name, key) in roles" :value="key" :key="key">{{ name }}</option></select></label><p class="notice">{{ descriptions[form.role] }}</p><fieldset><legend>الفروع المسموحة</legend><label class="check" v-for="b in session.branches" :key="b.uuid"><input type="checkbox" v-model="form.branch_uuids" :value="b.uuid">{{ b.name }}</label></fieldset><label class="check"><input type="checkbox" v-model="form.is_active">حساب نشط</label><p v-if="selected" class="muted">حفظ التعديل يُنهي جلسات المستخدم الحالية لتطبيق الصلاحيات.</p></div><div class="modal-actions"><button type="button" :disabled="busy" @click="modal = false"><FinanceIcon name="x" />إلغاء</button><button class="primary" :disabled="busy || !form.branch_uuids.length"><FinanceIcon name="badge-check" />{{ busy ? 'جارٍ الحفظ…' : 'حفظ المستخدم' }}</button></div></form></FinanceModal></template>
